// Payload Error Trigger: { execution: { id, url, error, lastNodeExecuted, mode }, workflow: { id, name } }
const j = $input.first().json;
const exec = j.execution || {};
const wf = j.workflow || {};
const err = exec.error || {};

const namaWf = wf.name || '-';
const namaNode = (err.node && err.node.name) || exec.lastNodeExecuted || '-';
const pesanErr = err.message || err.description || 'Tidak diketahui';
const linkEksekusi = exec.url || '-';
const waktu = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', hour12: false });

// Template alert 8a — docs/copywriting-pesan.md (order_id tidak tersedia di payload trigger; lihat link eksekusi)
const teks = `🚨 *[hariH] Workflow GAGAL*\nWF: ${namaWf}\nNode: ${namaNode}\nError: ${pesanErr}\nWaktu: ${waktu} WIB\n\nCek eksekusi: ${linkEksekusi}\nCustomer mungkin sudah bayar tapi belum menerima apa pun — prioritaskan.`;

// Normalisasi nomor WA owner (fungsi bersama T2.14, versi ringkas)
let ownerWa = String($env.OWNER_WA || '').replace(/\D/g, '');
if (ownerWa.startsWith('0')) ownerWa = '62' + ownerWa.slice(1);
else if (ownerWa.startsWith('8')) ownerWa = '62' + ownerWa;

const emailPayload = {
  sender: { name: $env.BREVO_SENDER_NAME || 'hariH', email: $env.BREVO_SENDER_EMAIL },
  to: [{ email: $env.OWNER_EMAIL }],
  subject: `🚨 [hariH] Workflow GAGAL: ${namaWf}`,
  htmlContent: `<pre style="font-family:Arial,Helvetica,sans-serif;white-space:pre-wrap;font-size:14px;color:#333">${teks.replace(/\*/g, '')}</pre>`,
};

return [{ json: { teks, owner_wa: ownerWa, email_payload: emailPayload } }];
